mapper.select:
SELECT CASE WHEN COUNT(*) > 0 THEN 1 ELSE 0 END
FROM TRAVEL_INFO
WHERE MEMBER_EMAIL = #{memberEmail}

WITH distinct_info AS ( SELECT DISTINCT ti.* FROM TRAVEL_INFO ti INNER JOIN TRAVEL_PLAN tp ON ti.INFO_ID = tp.INFO_ID ), paginated_info AS ( SELECT ti.*, ROW_NUMBER() OVER (ORDER BY ti.INFO_ID) AS rn FROM distinct_info ti
LOWER(ti.info_name) LIKE '%' || LOWER(#{searchKeyword}) || '%' OR LOWER(ti.trip_place) LIKE '%' || LOWER(#{searchKeyword}) || '%'
) SELECT * FROM paginated_info WHERE rn BETWEEN #{offset} + 1 AND #{offset} + #{pageSize}

WITH distinct_info AS ( SELECT DISTINCT ti.* FROM TRAVEL_INFO ti INNER JOIN TRAVEL_PLAN tp ON ti.INFO_ID = tp.INFO_ID ), filtered_info AS ( SELECT ti.* FROM distinct_info ti
LOWER(ti.info_name) LIKE '%' || LOWER(#{searchKeyword}) || '%' OR LOWER(ti.trip_place) LIKE '%' || LOWER(#{searchKeyword}) || '%'
) SELECT COUNT(*) FROM filtered_info

mapper.insert:
INSERT INTO travel_info (info_id, member_email, info_name, trip_place, start_date, end_date, who_tag, style_tag)
VALUES (info_id_seq.NEXTVAL, #{member_email}, #{info_name}, #{trip_place}, #{start_date}, #{end_date}, #{who_tag}, #{style_tag})
RETURNING info_id INTO #{info_id}
